#!/bin/bash
set -euo pipefail
umask 077
VW_DOMAIN="${VW_DOMAIN:-vault.example.com}"
VW_PORT="${VW_PORT:-8081}"
VW_USER="${VW_USER:-vaultwarden}"
VW_GROUP="${VW_GROUP:-vaultwarden}"
VW_BIN_DIR="${VW_BIN_DIR:-/usr/local/bin}"
VW_DATA_DIR="${VW_DATA_DIR:-/var/lib/vaultwarden}"
VW_WEB_DIR="${VW_WEB_DIR:-/var/lib/vaultwarden/web-vault}"
VW_ENV_FILE="${VW_ENV_FILE:-/etc/vaultwarden.env}"
VW_LOG_FILE="${VW_LOG_FILE:-/var/log/vaultwarden/vaultwarden.log}"
VW_BACKUP_DIR="${VW_BACKUP_DIR:-/opt/vaultwarden-backups}"
BACKUP_KEEP_DAYS="${BACKUP_KEEP_DAYS:-30}"
SIGNUPS_ALLOWED="${SIGNUPS_ALLOWED:-true}"
ENABLE_HTTPS="${ENABLE_HTTPS:-true}"
CERTBOT_EMAIL="${CERTBOT_EMAIL:-}"
VW_IMAGE_REPO="${VW_IMAGE_REPO:-vaultwarden/server}"
VW_IMAGE_TAG="${VW_IMAGE_TAG:-1.36.0-alpine}"
WEB_VAULT_VER="${WEB_VAULT_VER:-}"
EXTRACT_TOOL_COMMIT="${EXTRACT_TOOL_COMMIT:-4273b2796da5055e431b4db5efe29a71bba12b45}"
EXTRACT_TOOL_URL="https://raw.githubusercontent.com/jjlin/docker-image-extract/${EXTRACT_TOOL_COMMIT}/docker-image-extract"
EXTRACT_TOOL_SHA256="${EXTRACT_TOOL_SHA256:-a58f4995f568d66d9908649d4df7fc8c36f72096ca5e01f4c2c4291285125685}"
VW_BIN="${VW_BIN_DIR}/vaultwarden"
CONFIG_KEYS=(
  VW_DOMAIN VW_PORT VW_USER VW_GROUP VW_BIN_DIR VW_DATA_DIR VW_WEB_DIR
  VW_ENV_FILE VW_LOG_FILE VW_BACKUP_DIR BACKUP_KEEP_DAYS SIGNUPS_ALLOWED
  ENABLE_HTTPS CERTBOT_EMAIL VW_IMAGE_REPO VW_IMAGE_TAG WEB_VAULT_VER
  EXTRACT_TOOL_COMMIT EXTRACT_TOOL_SHA256
)
_VW_DERIVE_PATHS() {
  VW_BIN="${VW_BIN_DIR}/vaultwarden"
  # Legacy configs saved when EXTRACT_TOOL_COMMIT defaulted to the unpinned
  # "main" ref keep that value; migrate it to the pinned default so the
  # pinned SHA verification stays consistent.
  if [[ "${EXTRACT_TOOL_COMMIT:-}" == "main" ]]; then
    EXTRACT_TOOL_COMMIT="4273b2796da5055e431b4db5efe29a71bba12b45"
  fi
  EXTRACT_TOOL_URL="https://raw.githubusercontent.com/jjlin/docker-image-extract/${EXTRACT_TOOL_COMMIT}/docker-image-extract"
}
APP_CONFIG_DERIVE_HOOK=_VW_DERIVE_PATHS
_vw_doctor_service_name() {
  printf 'vaultwarden\n'
}
APP_DOCTOR_SERVICE_FN=_vw_doctor_service_name
_vw_remove_dir_or_error() {
  local path="$1" name="$2" success_message="$3"
  if ! safe_rm_dir "$path" "$name"; then
    error "$(t app.vaultwarden.error.remove_dir "$path")"
  fi
  success "$success_message"
}
_vw_remove_file_or_error() {
  local path="$1" name="$2"
  require_safe_path "$name" "$path"
  if ! rm -f "$path"; then
    error "$(t app.vaultwarden.error.remove_file "$path")"
  fi
}
_require_safe_vw_bin_path() {
  [[ "$VW_BIN" = /* && "$(dirname "$VW_BIN")" != "/" && "$(basename "$VW_BIN")" == "vaultwarden" ]] \
    || error "$(t error.unsafe_path "VW_BIN" "${VW_BIN:-empty}")"
}
app_conf_register_legacy "/etc/vaultwarden_deploy.conf"
CONF_FILE="$(app_conf_file)"
LOCK_FILE="$(app_lock_file)"
preflight_check() {
  [[ $EUID -ne 0 ]] && error "$(t error.root_required "$0" "")"
  if ! command -v apt-get &>/dev/null; then
    error "$(t app.vaultwarden.error.apt_only)"
  fi
  ARCH=$(uname -m)
  case $ARCH in
    x86_64)  : ;;
    aarch64) : ;;
    armv7l)  : ;;
    *) error "$(t app.vaultwarden.error.arch "$ARCH")" ;;
  esac
  _validate_config_values
}
check_connectivity() {
  app_check_connectivity app.vaultwarden.error.registry_unreachable \
    "https://auth.docker.io/token" \
    "https://registry-1.docker.io/v2/" \
    "https://api.github.com"
}
_validate_config_values() {
  app_validate_port "$VW_PORT" "VW_PORT"
  if ! is_valid_dns_name "$VW_DOMAIN"; then
    error "$(t app.vaultwarden.error.domain_invalid "$VW_DOMAIN")"
  fi
  app_validate_bool "ENABLE_HTTPS" "$ENABLE_HTTPS"
  app_validate_bool "SIGNUPS_ALLOWED" "$SIGNUPS_ALLOWED"
  app_validate_system_name "VW_USER" "$VW_USER"
  app_validate_system_name "VW_GROUP" "$VW_GROUP"
  if [[ -n "${CERTBOT_EMAIL:-}" ]]; then
    app_validate_email "CERTBOT_EMAIL" "$CERTBOT_EMAIL"
  fi
  app_validate_image_repo "VW_IMAGE_REPO" "$VW_IMAGE_REPO"
  app_validate_image_tag "VW_IMAGE_TAG" "$VW_IMAGE_TAG"
  app_validate_git_ref "EXTRACT_TOOL_COMMIT" "$EXTRACT_TOOL_COMMIT"
  app_validate_sha256 "EXTRACT_TOOL_SHA256" "$EXTRACT_TOOL_SHA256"
  if [[ -n "${WEB_VAULT_VER:-}" ]]; then
    app_validate_release_version "WEB_VAULT_VER" "$WEB_VAULT_VER"
  fi
  require_safe_path "VW_DATA_DIR" "$VW_DATA_DIR"
  require_safe_path "VW_WEB_DIR" "$VW_WEB_DIR"
  require_safe_path "LOG_DIR" "$(dirname "$VW_LOG_FILE")"
  require_safe_path "VW_BACKUP_DIR" "$VW_BACKUP_DIR"
  _require_safe_vw_bin_path
}
get_installed_version() {
  local version
  if [[ ! -x "$VW_BIN" ]]; then
    t app.vaultwarden.status.not_installed
    return 0
  fi
  version=$("$VW_BIN" --version 2>/dev/null | awk 'NF >= 2 { print $2; exit }' || true)
  if [[ -n "$version" ]]; then
    printf '%s\n' "$version"
  else
    t status.unknown
  fi
}
get_latest_webvault_ver() {
  local json tag
  json=$(curl -fsSL --max-time 15 \
    "https://api.github.com/repos/dani-garcia/bw_web_builds/releases/latest" 2>/dev/null) || true
  [[ -z "$json" ]] && { echo ""; return; }
  tag="$(json_tag_name "$json" --strip-v)"
  if [[ "$tag" =~ ^[0-9]+\.[0-9]+ ]]; then
    echo "$tag"
  else
    echo ""
  fi
}
_verify_web_vault_archive() {
  local archive="$1"
  local mode="${2:-fatal}"
  if [[ ! -s "$archive" ]]; then
    if ! rm -f "$archive"; then
      warn "$(t app.vaultwarden.warn.web_vault_archive_cleanup_failed "$archive")"
    fi
    if [[ "$mode" == "fatal" ]]; then
      error "$(t app.vaultwarden.error.web_vault_archive_empty)"
    fi
    warn "$(t app.vaultwarden.error.web_vault_archive_empty)"
    return 1
  fi
  local size
  size=$(wc -c < "$archive")
  if [[ "$size" -lt 65536 ]]; then
    if ! rm -f "$archive"; then
      warn "$(t app.vaultwarden.warn.web_vault_archive_cleanup_failed "$archive")"
    fi
    if [[ "$mode" == "fatal" ]]; then
      error "$(t app.vaultwarden.error.web_vault_archive_small "$size")"
    fi
    warn "$(t app.vaultwarden.error.web_vault_archive_small "$size")"
    return 1
  fi
  local magic
  magic=$(od -A n -t x1 -N 2 "$archive" 2>/dev/null | tr -d ' \n' || true)
  if [[ "$magic" != "1f8b" ]]; then
    if ! rm -f "$archive"; then
      warn "$(t app.vaultwarden.warn.web_vault_archive_cleanup_failed "$archive")"
    fi
    if [[ "$mode" == "fatal" ]]; then
      error "$(t app.vaultwarden.error.web_vault_archive_format "${magic:-read failed}")"
    fi
    warn "$(t app.vaultwarden.error.web_vault_archive_format "${magic:-read failed}")"
    return 1
  fi
}
extract_binary() {
  local workdir="$1"
  local platform="$2"
  info "$(t app.vaultwarden.info.download_extract_tool)"
  curl -fsSL --max-time 30 -o "${workdir}/docker-image-extract" "$EXTRACT_TOOL_URL" \
    || error "$(t app.vaultwarden.error.extract_tool_download)"
  [[ -s "${workdir}/docker-image-extract" ]] || error "$(t app.vaultwarden.error.extract_tool_empty)"
  head -1 "${workdir}/docker-image-extract" | grep -q '^#!' \
    || error "$(t app.vaultwarden.error.extract_tool_shebang)"
  local _die_size
  _die_size=$(wc -c < "${workdir}/docker-image-extract")
  [[ "$_die_size" -lt 4096 ]] \
    && error "$(t app.vaultwarden.error.extract_tool_small "$_die_size")"
  grep -q 'registry' "${workdir}/docker-image-extract" \
    || error "$(t app.vaultwarden.error.extract_tool_content)"
  if [[ -z "${EXTRACT_TOOL_SHA256:-}" ]]; then
    error "$(t app.vaultwarden.error.extract_tool_sha_missing)"
  fi
  local _actual_sha256
  if command -v sha256sum >/dev/null 2>&1; then
    if ! _actual_sha256=$(sha256sum "${workdir}/docker-image-extract" | awk '{print $1}'); then
      error "$(t app.vaultwarden.error.extract_tool_sha "$EXTRACT_TOOL_SHA256" "${_actual_sha256:-unavailable}")"
    fi
  elif command -v shasum >/dev/null 2>&1; then
    if ! _actual_sha256=$(shasum -a 256 "${workdir}/docker-image-extract" | awk '{print $1}'); then
      error "$(t app.vaultwarden.error.extract_tool_sha "$EXTRACT_TOOL_SHA256" "${_actual_sha256:-unavailable}")"
    fi
  else
    error "$(t app.vaultwarden.error.extract_tool_sha_tool_missing)"
  fi
  if [[ "$_actual_sha256" != "$EXTRACT_TOOL_SHA256" ]]; then
    error "$(t app.vaultwarden.error.extract_tool_sha "$EXTRACT_TOOL_SHA256" "$_actual_sha256")"
  fi
  success "$(t app.vaultwarden.success.extract_tool_sha)"
  if ! chmod +x "${workdir}/docker-image-extract"; then
    error "$(t app.vaultwarden.error.extract_tool_download)"
  fi
  info "$(t app.vaultwarden.info.extract_image "$VW_IMAGE_REPO" "$VW_IMAGE_TAG" "$platform")"
  info "$(t app.vaultwarden.info.first_download_wait)"
  local out_dir="${workdir}/image_output"
  if ! mkdir -p "$out_dir"; then
    error "$(t app.vaultwarden.error.image_extract)"
  fi
  bash "${workdir}/docker-image-extract" \
    -p "$platform" \
    -o "$out_dir" \
    "${VW_IMAGE_REPO}:${VW_IMAGE_TAG}" >&2 \
    || error "$(t app.vaultwarden.error.image_extract)"
  local bin_path
  bin_path=$(find "$out_dir" -type f -name "vaultwarden" | head -1 || true)
  [[ -z "$bin_path" ]] && error "$(t app.vaultwarden.error.binary_missing_image)"
  local _bin_size
  _bin_size=$(wc -c < "$bin_path")
  [[ "$_bin_size" -lt 1048576 ]] \
    && error "$(t app.vaultwarden.error.binary_too_small "$_bin_size")"
  if ! head -c 4 "$bin_path" | grep -qP '^\x7fELF' 2>/dev/null; then
    local _magic
    _magic=$(od -A n -t x1 -N 4 "$bin_path" 2>/dev/null | tr -d ' \n' || true)
    [[ "$_magic" != "7f454c46" ]] \
      && error "$(t app.vaultwarden.error.binary_not_elf)"
  fi
  local _expected_em _actual_em
  case "$platform" in
    linux/amd64)  _expected_em="3e00" ;;
    linux/arm64)  _expected_em="b700" ;;
    linux/arm/v7) _expected_em="2800" ;;
    *)            _expected_em="" ;;
  esac
  if [[ -n "$_expected_em" ]]; then
    _actual_em=$(od -A n -t x1 -j 18 -N 2 "$bin_path" 2>/dev/null | tr -d ' \n' || true)
    if [[ "$_actual_em" != "$_expected_em" ]]; then
      error "$(t app.vaultwarden.error.elf_machine "$_expected_em" "$platform" "$_actual_em")"
    fi
  fi
  chmod +x "$bin_path"
  local webvault_path
  webvault_path=$(find "$out_dir" -type d -name "web-vault" | head -1 || true)
  echo "$webvault_path" > "${workdir}/.webvault_path"
  echo "$bin_path"
}
restore_web_vault_backup() {
  local backup_dir="$1"
  [[ -d "$backup_dir" ]] || return 1
  if ! safe_rm_dir "$VW_WEB_DIR" "VW_WEB_DIR"; then
    return 1
  fi
  if ! mv "$backup_dir" "$VW_WEB_DIR"; then
    return 1
  fi
  require_safe_path "VW_WEB_DIR" "$VW_WEB_DIR"
  if ! chown -R "${VW_USER}:${VW_GROUP}" "$VW_WEB_DIR"; then
    return 1
  fi
  if ! chmod -R 750 "$VW_WEB_DIR"; then
    return 1
  fi
}
deploy_web_vault_from_dir() {
  local source_dir="$1" backup_dir="$2"
  local staged_dir
  [[ -d "$source_dir" ]] || return 1
  require_safe_path "VW_WEB_DIR" "$VW_WEB_DIR"
  if ! mkdir -p "$(dirname "$VW_WEB_DIR")"; then
    return 1
  fi
  if ! staged_dir=$(mktemp -d "${VW_WEB_DIR}.new.XXXXXX"); then
    return 1
  fi
  if ! cp -a "${source_dir}/." "$staged_dir/" \
      || ! chown -R "${VW_USER}:${VW_GROUP}" "$staged_dir" \
      || ! chmod -R 750 "$staged_dir"; then
    rm -rf "$staged_dir"
    return 1
  fi
  if [[ -e "$VW_WEB_DIR" || -L "$VW_WEB_DIR" ]]; then
    if ! mv "$VW_WEB_DIR" "$backup_dir"; then
      rm -rf "$staged_dir"
      return 1
    fi
  fi
  if mv "$staged_dir" "$VW_WEB_DIR"; then
    return 0
  fi
  rm -rf "$staged_dir"
  if [[ -d "$backup_dir" ]]; then
    restore_web_vault_backup "$backup_dir" || return 1
  fi
  return 1
}
install_vaultwarden_binary() {
  local source_bin="$1"
  local bin_tmp
  if ! mkdir -p "$VW_BIN_DIR"; then
    return 1
  fi
  if ! bin_tmp=$(mktemp "${VW_BIN}.XXXXXX"); then
    return 1
  fi
  if ! install -m 755 -o root -g root "$source_bin" "$bin_tmp" \
      || ! mv "$bin_tmp" "$VW_BIN"; then
    if ! rm -f "$bin_tmp"; then
      warn "$(t app.vaultwarden.warn.tmp_binary_cleanup_failed "$bin_tmp")"
    fi
    return 1
  fi
}
backup_vaultwarden_binary() {
  local backup_path="$1"
  local backup_tmp
  if ! backup_tmp=$(mktemp "${backup_path}.XXXXXX"); then
    error "$(t app.vaultwarden.error.binary_install "$VW_BIN")"
  fi
  if ! cp "$VW_BIN" "$backup_tmp" || ! mv "$backup_tmp" "$backup_path"; then
    rm -f "$backup_tmp"
    return 1
  fi
}
_write_fail2ban_config_file() {
  local fail2ban_conf="$1"
  local fail2ban_tmp
  if ! fail2ban_tmp=$(mktemp "${fail2ban_conf}.XXXXXX"); then
    error "$(t app.vaultwarden.error.fail2ban_write "$fail2ban_conf")"
  fi
  if ! cat > "$fail2ban_tmp"; then
    rm -f "$fail2ban_tmp"
    error "$(t app.vaultwarden.error.fail2ban_write "$fail2ban_conf")"
  fi
  if ! chmod 644 "$fail2ban_tmp" \
      || ! chown root:root "$fail2ban_tmp" \
      || ! mv "$fail2ban_tmp" "$fail2ban_conf"; then
    rm -f "$fail2ban_tmp"
    error "$(t app.vaultwarden.error.fail2ban_write "$fail2ban_conf")"
  fi
}
do_install() {
  show_banner
  preflight_check
  acquire_lock
  check_connectivity
  local _c
  if [[ -x "$VW_BIN" ]]; then
    warn "$(t app.vaultwarden.warn.installed "$VW_BIN" "$(get_installed_version)")"
    warn "$(t app.vaultwarden.warn.reinstall)"
    if deploy_assume_yes; then
      _c="y"
    else
      prompt "$(t app.vaultwarden.prompt.force_reinstall)"
      read -r _c
    fi
    [[ "${_c,,}" != "y" ]] && { info "$(t app.vaultwarden.info.install_cancelled_update)"; exit 0; }
  fi
  step "$(t app.vaultwarden.step.wizard)"
  if [[ "$VW_DOMAIN" == "vault.example.com" ]]; then
    if deploy_assume_yes; then
      error "$(t app.vaultwarden.error.noninteractive_domain)"
    else
      while true; do
        prompt "$(t app.vaultwarden.prompt.domain)"
        local _input; read -r _input
        [[ -z "$_input" ]] && { warn "$(t app.vaultwarden.warn.domain_empty)"; continue; }
        if ! is_valid_dns_name "$_input"; then
          warn "$(t app.vaultwarden.warn.domain_invalid "$_input")"
          continue
        fi
        VW_DOMAIN="$_input"
        break
      done
    fi
  fi
  if [[ "$ENABLE_HTTPS" == "true" ]] && [[ -z "$CERTBOT_EMAIL" ]]; then
    if deploy_assume_yes; then
      error "$(t app.vaultwarden.error.noninteractive_email)"
    else
      while true; do
        prompt "$(t app.vaultwarden.prompt.email)"
        local _email; read -r _email
        [[ -z "$_email" ]] && { warn "$(t app.vaultwarden.warn.email_empty)"; continue; }
        if ! app_is_valid_email "$_email"; then
          warn "$(t app.vaultwarden.warn.email_invalid "$_email")"
          continue
        fi
        CERTBOT_EMAIL="$_email"
        break
      done
    fi
  fi
  echo ""
  info "$(t app.vaultwarden.info.domain "$VW_DOMAIN")"
  info "$(t app.vaultwarden.info.listen_port "$VW_PORT")"
  info "$(t app.vaultwarden.info.binary "$VW_BIN")"
  info "$(t app.vaultwarden.info.data_dir "$VW_DATA_DIR")"
  info "$(t app.vaultwarden.info.web_vault "$VW_WEB_DIR")"
  info "$(t app.vaultwarden.info.run_user "$VW_USER")"
  info "$(t app.vaultwarden.info.https "$ENABLE_HTTPS")"
  echo ""
  if deploy_assume_yes; then
    _c="y"
  else
    prompt "$(t app.vaultwarden.prompt.confirm_config)"
    read -r _c
  fi
  [[ "${_c,,}" != "y" ]] && { info "$(t app.vaultwarden.info.config_cancelled)"; exit 0; }
  step "$(t app.vaultwarden.step.deps)"
  if ! DEBIAN_FRONTEND=noninteractive apt-get update -qq; then
    warn "$(t app.vaultwarden.warn.apt_update)"
  fi
  if ! DEBIAN_FRONTEND=noninteractive apt-get install -y -qq \
    curl wget ca-certificates \
    nginx certbot python3-certbot-nginx \
    sqlite3 argon2 openssl fail2ban \
    logrotate; then
