# ── Logging ───────────────────────────────────────────────────
LOG_FILE=${VW_LOG_FILE}
LOG_LEVEL=info
EXTENDED_LOGGING=true

# ── Security hardening ────────────────────────────────────────
LOGIN_RATELIMIT_MAX_BURST=10
LOGIN_RATELIMIT_SECONDS=60
ADMIN_RATELIMIT_MAX_BURST=10
ADMIN_RATELIMIT_SECONDS=60
IP_HEADER=X-Real-IP

# ── Attachment limits in KiB ──────────────────────────────────
