# ── Optional SMTP settings ────────────────────────────────────
# SMTP_HOST=smtp.example.com
# SMTP_PORT=587
# SMTP_SECURITY=starttls
# SMTP_USERNAME=your@email.com
# SMTP_PASSWORD=your_password
# SMTP_FROM=no-reply@${VW_DOMAIN}
