# Vaultwarden reverse proxy configuration for the HTTP bootstrap phase.
server {
    listen 80;
    listen [::]:80;
    server_name ${VW_DOMAIN};

    # Let's Encrypt ACME challenge
    location /.well-known/acme-challenge/ {
