# Vaultwarden reverse proxy configuration for HTTP to HTTPS redirect.
server {
    listen 80;
    listen [::]:80;
    server_name ${VW_DOMAIN};

    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }
    location / {
